class Solution:
    def countArrangement(self, n: int) -> int:
        count = 0
        used = [False] * (n + 1)

        def backtrack(pos: int) -> None:
            nonlocal count
            if pos == n + 1:
                count += 1
                return
            for value in range(1, n + 1):
                if used[value]:
                    continue
                if value % pos == 0 or pos % value == 0:
                    used[value] = True
                    backtrack(pos + 1)
                    used[value] = False

        backtrack(1)
        return count

